"import os

def create_case():
    # Helper function to write files
    def write_file(path, content):
        directory = os.path.dirname(path)
        if directory:
            os.makedirs(directory, exist_ok=True)
        with open(path, 'w') as f:
            f.write(content)

    # Template for FoamFile header
    def foam_header(location, obj):
