{{
    version     2.0;
    format      ascii;
    class       dictionary;
    location    "{location}";
    object      {obj};
}}
// * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * //
"""

    # --- system/controlDict ---
    control_dict_content = f"""{foam_header("system", "controlDict")}
application     buoyantFoam;

startFrom       startTime;

startTime       0;

stopAt          endTime;

endTime         1000;

